import {
  createContext,
  useContext,
  useState,
  Dispatch,
  SetStateAction,
  ReactNode,
} from 'react';

export const CountStateContext = createContext<number>(0);
export const CountDispatchContext = createContext<Dispatch<SetStateAction<number>>>(
  () => {},
);

export function CountProvider({ children }: { children: ReactNode }) {
  const [count, setCount] = useState<number>(0);
  return (
    <CountStateContext.Provider value={count}>
      <CountDispatchContext.Provider value={setCount}>
        {children}
      </CountDispatchContext.Provider>
    </CountStateContext.Provider>
  );
}

export function useCountState() {
  return useContext(CountStateContext);
}

export function useCountDispatch() {
  return useContext(CountDispatchContext);
}

export function IncrementButton() {
  const setCount = useCountDispatch();
  return <button onClick={() => setCount((c) => c + 1)}>+1</button>;
}
